1	// Grok Bot–style sidebar: docked on desktop as either the expanded panel or a compact avatar
2	// rail, resizable by its edge; a slide-in overlay (always expanded) on mobile.
3	import { AnimatePresence, animate, type Transition, useMotionValue, useReducedMotion, useTransform } from "motion/react";
4	import * as m from "motion/react-m";
5	import { type KeyboardEvent, type PointerEvent, useEffect, useRef, useState } from "react";
6	import { panelSwap, SPRING_SNAP, sidebarMobile, sidebarResize } from "@/lib/motion";
7	import { clampWidth, readSidebarCompact, readSidebarWidth, SIDEBAR, writeSidebarLayout } from "@/lib/sidebar";
8	import { ExpandedPanel, RailPanel, type SidebarPanelProps } from "./SidebarPanels";
9	
10	export type { SidebarSearch } from "./SidebarPanels";
11	
12	/** How long pointer moves are ignored after a snap, so the spring isn't cut short. */
13	const SNAP_SETTLE_MS = 180;
14	
15	export function Sidebar({ docked, ...props }: SidebarPanelProps & { docked: boolean }) {
16	  return docked ? <DockedSidebar {...props} /> : <OverlaySidebar {...props} />;
17	}
18	
19	/** Mobile: slides in from the start edge (App mounts it under AnimatePresence). */
20	function OverlaySidebar(props: SidebarPanelProps) {
21	  return (
22	    <m.aside
23	      data-testid="sidebar"
24	      data-layout="overlay"
25	      variants={sidebarMobile}
26	      initial="hidden"
27	      animate="visible"
28	      exit="hidden"
29	      className="absolute inset-y-0 start-0 z-40 flex w-[calc(100%-48px)] max-w-[284px] flex-col border-e border-sidebar-border bg-sidebar"
30	    >
31	      <ExpandedPanel {...props} />
32	    </m.aside>
33	  );
34	}
35	
36	/**
37	 * Desktop: always docked. Width is a motion value so dragging follows the pointer 1:1 with
38	 * no animation; switching layouts animates it (mirrored tween for button/double-click/Enter,
39	 * a fast spring when a drag crosses a snap threshold) while the panels cross-fade.
40	 */
41	function DockedSidebar(props: SidebarPanelProps) {
42	  const reduce = useReducedMotion();
43	  const [compact, setCompact] = useState(readSidebarCompact);
44	  const [width, setWidth] = useState(readSidebarWidth);
45	  const [dragging, setDragging] = useState(false);
46	  const compactRef = useRef(compact);
47	  const widthRef = useRef(width);
48	  const size = useMotionValue(compact ? SIDEBAR.RAIL : width);
49	  // The expanded panel never lays out narrower than MIN, so it doesn't reflow while shrinking.
50	  const panelWidth = useTransform(size, (value) => Math.max(value, SIDEBAR.MIN));
51	  // origin: the expanded width when the drag began — what a snap back to expanded restores.
52	  const drag = useRef<{ startX: number; base: number; origin: number } | null>(null);
53	  const settleUntil = useRef(0);
54	
55	  const commit = (nextWidth: number, nextCompact: boolean) => {
56	    widthRef.current = nextWidth;
57	    compactRef.current = nextCompact;
58	    setWidth(nextWidth);
59	    setCompact(nextCompact);
60	    writeSidebarLayout(nextWidth, nextCompact);
61	  };
62	
63	  const animateSize = (target: number, transition: Transition) => {
64	    if (reduce) {
65	      size.jump(target);
66	      return;
67	    }
68	    settleUntil.current = performance.now() + SNAP_SETTLE_MS;
69	    animate(size, target, transition);
70	  };
71	
72	  const setMode = (nextCompact: boolean, how: "toggle" | "snap") => {
73	    if (nextCompact === compactRef.current) return;
74	    commit(widthRef.current, nextCompact);
75	    animateSize(nextCompact ? SIDEBAR.RAIL : widthRef.current, how === "snap" ? SPRING_SNAP : sidebarResize(!nextCompact));
76	  };
77	  const toggle = () => setMode(!compactRef.current, "toggle");
78	
79	  // No text selection and a resize cursor everywhere while dragging.
80	  useEffect(() => {
81	    if (!dragging) return;
82	    const { style } = document.body;
83	    const previous = { userSelect: style.userSelect, cursor: style.cursor };
84	    style.userSelect = "none";
85	    style.cursor = "col-resize";
86	    return () => {
87	      style.userSelect = previous.userSelect;
88	      style.cursor = previous.cursor;
89	    };
90	  }, [dragging]);
91	
92	  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
93	    if (event.button !== 0) return;
94	    event.preventDefault();
95	    event.currentTarget.setPointerCapture(event.pointerId);
96	    drag.current = {
97	      startX: event.clientX,
98	      base: compactRef.current ? SIDEBAR.RAIL : size.get(),
99	      origin: widthRef.current,
100	    };
101	    setDragging(true);
102	  };
103	
104	  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
105	    const current = drag.current;
106	    if (!current || performance.now() < settleUntil.current) return;
107	    const candidate = current.base + (event.clientX - current.startX);
108	    if (compactRef.current) {
109	      if (candidate > SIDEBAR.SNAP_TO_EXPANDED) {
110	        setMode(false, "snap");
111	        drag.current = { ...current, startX: event.clientX, base: widthRef.current };
112	      }
113	      return;
114	    }
115	    if (candidate < SIDEBAR.SNAP_TO_RAIL) {
116	      // The edge passed through MIN on the way here; remember the width the drag started at.
117	      widthRef.current = current.origin;
118	      setMode(true, "snap");
119	      drag.current = { ...current, startX: event.clientX, base: SIDEBAR.RAIL };
120	      return;
121	    }
122	    // Between MIN and the snap threshold the edge holds at MIN (a little resistance).
123	    const next = clampWidth(candidate);
124	    size.jump(next);
125	    widthRef.current = next;
126	  };
127	
128	  const endDrag = () => {
129	    if (!drag.current) return;
130	    drag.current = null;
131	    setDragging(false);
132	    commit(widthRef.current, compactRef.current);
133	  };
134	
135	  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
136	    if (event.key === "Enter" || event.key === " ") {
137	      event.preventDefault();
138	      toggle();
139	      return;
140	    }
141	    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
142	    event.preventDefault();
143	    const step = event.shiftKey ? SIDEBAR.STEP_LARGE : SIDEBAR.STEP;
144	    const grow = event.key === "ArrowRight";
145	    if (compactRef.current) {
146	      if (grow) setMode(false, "toggle");
147	      return;
148	    }
149	    if (!grow && widthRef.current <= SIDEBAR.MIN) {
150	      setMode(true, "toggle");
151	      return;
152	    }
153	    const next = clampWidth(widthRef.current + (grow ? step : -step));
154	    size.jump(next);
155	    commit(next, false);
156	  };
157	
158	  const panelProps = { ...props, onToggleCompact: toggle };
159	
160	  return (
161	    <m.aside
162	      data-testid="sidebar"
163	      data-layout={compact ? "rail" : "expanded"}
164	      data-dragging={dragging || undefined}
165	      style={{ width: size }}
166	      className="relative h-full shrink-0 border-e border-sidebar-border bg-sidebar"
167	    >
168	      <div className="absolute inset-0 overflow-hidden">
169	        <AnimatePresence initial={false}>
170	          {compact ? (
171	            <m.div
172	              key="rail"
173	              variants={panelSwap}
174	              initial="hidden"
175	              animate="visible"
176	              exit="hidden"
177	              className="absolute inset-y-0 start-0"
178	              style={{ width: SIDEBAR.RAIL }}
179	            >
180	              <RailPanel {...panelProps} />
181	            </m.div>
182	          ) : (
183	            <m.div
184	              key="expanded"
185	              variants={panelSwap}
186	              initial="hidden"
187	              animate="visible"
188	              exit="hidden"
189	              className="absolute inset-y-0 start-0"
190	              style={{ width: panelWidth }}
191	            >
192	              <ExpandedPanel {...panelProps} />
193	            </m.div>
194	          )}
195	        </AnimatePresence>
196	      </div>
197	      {/* Resize handle on the end edge: drag, double-click, or keyboard (arrows resize, Enter toggles). */}
198	      <div
199	        role="separator"
200	        tabIndex={0}
201	        aria-orientation="vertical"
202	        aria-label="Resize sidebar"
203	        aria-valuemin={SIDEBAR.RAIL}
204	        aria-valuemax={SIDEBAR.MAX}
205	        aria-valuenow={compact ? SIDEBAR.RAIL : width}
206	        aria-valuetext={compact ? "Compact" : `${width} pixels`}
207	        data-testid="sidebar-resize"
208	        onPointerDown={onPointerDown}
209	        onPointerMove={onPointerMove}
210	        onPointerUp={endDrag}
211	        onPointerCancel={endDrag}
212	        onLostPointerCapture={endDrag}
213	        onDoubleClick={toggle}
214	        onKeyDown={onKeyDown}
215	        className="group absolute inset-y-0 -end-1.5 z-30 w-3 cursor-col-resize touch-none outline-none"
216	      >
217	        <span
218	          aria-hidden="true"
219	          className={`absolute inset-y-0 start-1/2 w-0.5 -translate-x-1/2 transition-colors duration-(--motion-fast) ease-(--ease-standard) group-hover:bg-ring/45 group-focus-visible:bg-ring ${
220	            dragging ? "bg-ring/70" : "bg-transparent"
221	          }`}
222	        />
223	      </div>
224	    </m.aside>
225	  );
226	}
