1	// Sidebar contents in the two layouts the shell uses (Grok Bot style): the expanded panel
2	// (featured orchestrator tile + "Specialists" rows) and the compact avatar rail.
3	// Row markup started from rakazo's bots sidebar (apps/web/src/pages/Shell.tsx ~2811-3263),
4	// Apache-2.0, github.com/elie222/rakazo@912c977.
5	import type { UIMessage } from "ai";
6	import { Moon, PanelLeftClose, PanelLeftOpen, Plus, Search, Sun, X } from "lucide-react";
7	import { AnimatePresence, type Variants } from "motion/react";
8	import * as m from "motion/react-m";
9	import { useEffect, useState } from "react";
10	import { BotAvatar } from "@/components/avatar/bot-avatar";
11	import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group";
12	import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
13	import type { AgentRowState } from "@/hooks/useAgentChat";
14	import type { AgentSummary } from "@/hooks/useAgents";
15	import { agentAvatarValue } from "@/lib/agent-avatar";
16	import { type ResolvedAppearance, setUiAppearance } from "@/lib/appearance";
17	import { messageTime } from "@/lib/chats";
18	import { messageText } from "@/lib/message-parts";
19	import { DURATION, enterTransition, exitTransition, fade, pop, SPRING, STAGGER, STAGGER_CAP } from "@/lib/motion";
20	import { groupAgents } from "@/lib/sidebar";
21	
22	export type SidebarSearch = {
23	  query: string;
24	  setQuery: (query: string) => void;
25	  open: boolean;
26	  setOpen: (open: boolean) => void;
27	};
28	
29	export type SidebarPanelProps = {
30	  agents: AgentSummary[];
31	  rows: Record<string, AgentRowState>;
32	  activeKey: string | null;
33	  onSelect: (key: string) => void;
34	  onNewChat: () => void;
35	  search: SidebarSearch;
36	  /** Switch between expanded and rail (absent on the mobile overlay). */
37	  onToggleCompact?: () => void;
38	};
39	
40	/** Items rise in one after another; a filtered-out row leaves the way it came. */
41	const itemVariants: Variants = {
42	  hidden: { opacity: 0, y: 6, transition: exitTransition(DURATION.base) },
43	  visible: (index: number = 0) => ({
44	    opacity: 1,
45	    y: 0,
46	    transition: enterTransition(DURATION.base, Math.min(index, STAGGER_CAP) * STAGGER),
47	  }),
48	};
49	
50	// The roster staggers in once per page load, not every time a panel remounts
51	// (expand/collapse, reopening the mobile overlay).
52	let rosterStaggered = false;
53	function useFirstLoadStagger(): boolean {
54	  const [stagger] = useState(() => !rosterStaggered);
55	  useEffect(() => {
56	    rosterStaggered = true;
57	  }, []);
58	  return stagger;
59	}
60	
61	type Badge = "working" | "error" | "unread" | null;
62	const badgeFor = (row: AgentRowState | undefined): Badge =>
63	  row?.running ? "working" : row?.error ? "error" : row?.unread ? "unread" : null;
64	
65	/**
66	 * Avatar with a corner badge: pulsing while working, red on failure, a dot when unread.
67	 * Specialist rows pass `activityOnly` because they show unread as an inline dot instead.
68	 */
69	function AgentAvatar({
70	  agent,
71	  size,
72	  row,
73	  activityOnly = false,
74	}: {
75	  agent: AgentSummary;
76	  size: number;
77	  row?: AgentRowState;
78	  activityOnly?: boolean;
79	}) {
80	  const status = badgeFor(row);
81	  const badge = activityOnly && status === "unread" ? null : status;
82	  return (
83	    <span className="relative inline-flex shrink-0">
84	      <BotAvatar
85	        color={agentAvatarValue(agent.id)}
86	        identity={agent.id}
87	        size={size}
88	        status={row?.running ? "running" : undefined}
89	      />
90	      <AnimatePresence initial={false}>
91	        {badge ? (
92	          <m.span
93	            key={badge}
94	            data-testid={`badge-${badge}`}
95	            aria-hidden="true"
96	            variants={pop}
97	            initial="hidden"
98	            animate="visible"
99	            exit="hidden"
100	            className="absolute -end-0.5 -top-0.5 grid h-3 w-3 place-items-center rounded-full bg-sidebar"
101	          >
102	            <span
103	              className={`h-2 w-2 rounded-full ${
104	                badge === "working" ? "bg-warning" : badge === "error" ? "bg-destructive" : "bg-foreground"
105	              }`}
106	              style={badge === "working" ? { animation: "rkPulse 1.2s ease-in-out infinite" } : undefined}
107	            />
108	          </m.span>
109	        ) : null}
110	      </AnimatePresence>
111	    </span>
112	  );
113	}
114	
115	const iconButton =
116	  "grid h-8 w-8 shrink-0 place-items-center rounded-lg text-muted-foreground/80 transition-colors duration-(--motion-fast) ease-(--ease-standard) hover:bg-sidebar-accent hover:text-foreground";
117	
118	/** Expanded layout: wordmark + search/new chat, featured tile, specialists, theme toggle. */
119	export function ExpandedPanel({ agents, rows, activeKey, onSelect, onNewChat, search, onToggleCompact }: SidebarPanelProps) {
120	  const stagger = useFirstLoadStagger();
121	  const needle = search.query.trim().toLowerCase();
122	  const matches = (agent: AgentSummary) =>
123	    !needle || `${agent.name} ${agent.description}`.toLowerCase().includes(needle);
124	  const { primary, specialists } = groupAgents(agents);
125	  const shownPrimary = primary.filter(matches);
126	  const shownSpecialists = specialists.filter(matches);
127	  const closeSearch = () => {
128	    search.setQuery("");
129	    search.setOpen(false);
130	  };
131	
132	  return (
133	    <div className="flex h-full min-h-0 flex-col">
134	      <div className="flex h-[52px] shrink-0 items-center gap-1 px-3 pt-2">
135	        <AnimatePresence mode="wait" initial={false}>
136	          {search.open ? (
137	            <m.div key="search" variants={fade} initial="hidden" animate="visible" exit="hidden" className="min-w-0 flex-1">
138	              <InputGroup className="h-8 rounded-lg border border-border bg-card text-muted-foreground focus-within:border-ring dark:bg-input">
139	                <InputGroupAddon>
140	                  <Search size={14} strokeWidth={1.8} aria-hidden="true" />
141	                </InputGroupAddon>
142	                <InputGroupInput
143	                  autoFocus
144	                  value={search.query}
145	                  onChange={(event) => search.setQuery(event.target.value)}
146	                  onKeyDown={(event) => {
147	                    if (event.key === "Escape") closeSearch();
148	                  }}
149	                  onBlur={() => {
150	                    if (!search.query.trim()) closeSearch();
151	                  }}
152	                  placeholder="Search agents"
153	                  aria-label="Search agents"
154	                  autoComplete="off"
155	                  name="sidebar-search"
156	                />
157	                <InputGroupAddon align="inline-end">
158	                  <button
159	                    type="button"
160	                    aria-label="Close search"
161	                    onMouseDown={(event) => event.preventDefault()}
162	                    onClick={closeSearch}
163	                    className="grid h-5 w-5 place-items-center rounded text-muted-foreground hover:text-foreground"
164	                  >
165	                    <X size={13} strokeWidth={1.8} />
166	                  </button>
167	                </InputGroupAddon>
168	              </InputGroup>
169	            </m.div>
170	          ) : (
171	            <m.span
172	              key="wordmark"
173	              variants={fade}
174	              initial="hidden"
175	              animate="visible"
176	              exit="hidden"
177	              className="min-w-0 flex-1 truncate ps-1.5 text-[15px] font-semibold tracking-tight text-foreground"
178	            >
179	              nlhack
180	            </m.span>
181	          )}
182	        </AnimatePresence>
183	        {search.open ? null : (
184	          <button type="button" aria-label="Search agents" title="Search" onClick={() => search.setOpen(true)} className={iconButton}>
185	            <Search size={16} strokeWidth={1.8} aria-hidden="true" />
186	          </button>
187	        )}
188	        <button type="button" aria-label="New chat" title="New chat" onClick={onNewChat} className={iconButton}>
189	          <Plus size={17} strokeWidth={1.8} aria-hidden="true" />
190	        </button>
191	        {onToggleCompact ? (
192	          <button
193	            type="button"
194	            aria-label="Collapse sidebar"
195	            title="Collapse sidebar"
196	            onClick={onToggleCompact}
197	            className={iconButton}
198	          >
199	            <PanelLeftClose size={16} strokeWidth={1.8} aria-hidden="true" />
200	          </button>
201	        ) : null}
202	      </div>
203	
204	      <nav aria-label="Agents" className="rk-scroll relative min-h-0 flex-1 overflow-y-auto overflow-x-hidden px-2.5 pb-3 pt-1">
205	        <AnimatePresence initial={stagger}>
206	          {shownPrimary.length > 0 ? (
207	            <m.div key="featured" layout="position" className="flex flex-wrap justify-center gap-2 px-0.5 pb-3 pt-1">
208	              {shownPrimary.map((agent, index) => {
209	                const selected = agent.key === activeKey;
210	                return (
211	                  <m.button
212	                    key={agent.key}
213	                    type="button"
214	                    data-testid="featured-agent"
215	                    custom={index}
216	                    variants={itemVariants}
217	                    initial="hidden"
218	                    animate="visible"
219	                    exit="hidden"
220	                    aria-current={selected ? "page" : undefined}
221	                    onClick={() => onSelect(agent.key)}
222	                    className={`flex w-24 flex-col items-center gap-2 rounded-2xl px-2 pb-2.5 pt-3 transition-colors duration-(--motion-fast) ease-(--ease-standard) ${
223	                      selected ? "bg-sidebar-accent" : "hover:bg-sidebar-accent/60"
224	                    }`}
225	                  >
226	                    <AgentAvatar agent={agent} size={56} row={rows[agent.key]} />
227	                    <span className="w-full truncate text-center text-[13px] font-medium text-foreground">
228	                      {agent.name}
229	                    </span>
230	                  </m.button>
231	                );
232	              })}
233	            </m.div>
234	          ) : null}
235	          {shownSpecialists.length > 0 ? (
236	            <m.p
237	              key="specialists-label"
238	              layout="position"
239	              variants={fade}
240	              initial="hidden"
241	              animate="visible"
242	              exit="hidden"
243	              className="px-2.5 pb-1.5 pt-1 text-[12px] font-medium text-muted-foreground/70"
244	            >
245	              Specialists
246	            </m.p>
247	          ) : null}
248	          {shownSpecialists.map((agent, index) => (
249	            <SpecialistRow
250	              key={agent.key}
251	              agent={agent}
252	              index={index + shownPrimary.length}
253	              row={rows[agent.key]}
254	              selected={agent.key === activeKey}
255	              onSelect={onSelect}
256	            />
257	          ))}
258	          {shownPrimary.length + shownSpecialists.length === 0 ? (
259	            <m.p
260	              key="no-match"
261	              variants={fade}
262	              initial="hidden"
263	              animate="visible"
264	              exit="hidden"
265	              className="px-2.5 py-6 text-center text-[13px] text-muted-foreground"
266	            >
267	              No agents match “{search.query}”.
268	            </m.p>
269	          ) : null}
270	        </AnimatePresence>
271	      </nav>
272	
273	      <ThemeToggle />
274	    </div>
275	  );
276	}
277	
278	function SpecialistRow({
279	  agent,
280	  index,
281	  row,
282	  selected,
283	  onSelect,
284	}: {
285	  agent: AgentSummary;
286	  index: number;
287	  row?: AgentRowState;
288	  selected: boolean;
289	  onSelect: (key: string) => void;
290	}) {
291	  const last = row?.messages.at(-1);
292	  const lastTime = last ? messageTime(last.id) : undefined;
293	  const status = row?.running ? "working" : row?.error ? "error" : "idle";
294	  // One line: the latest message, or the run state. Nothing before the first message.
