493	function previewText(message: UIMessage): string {
494	  const plain = messageText(message)
495	    .replace(/[#>*_`|]/g, "")
496	    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
497	    .replace(/\s+/g, " ")
498	    .trim();
499	  return plain && message.role === "user" ? `You: ${plain}` : plain;
