502	/** Time for today, weekday within a week, else a short date (as in rakazo's roster). */
503	function formatRosterTime(timestamp: number): string {
504	  const date = new Date(timestamp);
505	  const now = new Date();
506	  if (date.toDateString() === now.toDateString()) {
507	    return date.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
508	  }
509	  const days = (now.getTime() - timestamp) / 86_400_000;
510	  if (days < 7) return date.toLocaleDateString(undefined, { weekday: "short" });
511	  return date.toLocaleDateString(undefined, { month: "short", day: "numeric" });
512	}
