3	/**
4	 * Shared motion tokens. Every enter/exit pair is symmetric: the exit uses the same duration
5	 * and distance as the enter, and its easing is the exact time-reverse of the enter curve, so
6	 * an exit plays like the enter run backwards. Mirrored in CSS as --motion-* / --ease-* in
7	 * styles.css for Base UI overlays and CSS state transitions.
8	 */
9	
10	type Bezier = readonly [number, number, number, number];
11	
12	/** Seconds. */
13	export const DURATION = { fast: 0.15, base: 0.22, slow: 0.3 } as const;
14	
15	/** Pixels of travel for enter/exit offsets. */
16	export const DISTANCE = { sm: 4, md: 8, lg: 16 } as const;
17	
18	/** Delay between siblings in a staggered group (seconds). */
19	export const STAGGER = 0.035;
20	/** Most siblings that get their own stagger step; later ones share the last delay. */
21	export const STAGGER_CAP = 8;
22	
23	/** Time-reverse of a cubic-bezier: f'(t) = 1 - f(1 - t). */
24	export function mirrorBezier([x1, y1, x2, y2]: Bezier): Bezier {
25	  return [1 - x2, 1 - y2, 1 - x1, 1 - y1];
26	}
27	
28	/** Decelerating curve for things arriving. */
29	export const EASE_ENTER: Bezier = [0.22, 1, 0.36, 1];
30	/** Its exact mirror for things leaving: [0.64, 0, 0.78, 0]. */
31	export const EASE_EXIT: Bezier = mirrorBezier(EASE_ENTER);
32	/** Self-mirroring curve for two-way state changes (CSS hover/focus). */
33	export const EASE_STANDARD: Bezier = [0.45, 0, 0.55, 1];
34	
35	/** Critically damped spring for layout moves (same response in both directions). */
36	export const SPRING: Transition = { type: "spring", stiffness: 520, damping: 44, mass: 0.9 };
37	
38	export const enterTransition = (duration: number = DURATION.base, delay = 0): Transition => ({
39	  duration,
40	  delay,
41	  ease: EASE_ENTER,
42	});
43	export const exitTransition = (duration: number = DURATION.base, delay = 0): Transition => ({
44	  duration,
45	  delay,
46	  ease: EASE_EXIT,
47	});
48	
49	type Offset = { x?: number | string; y?: number | string; scale?: number };
50	
51	/**
52	 * `hidden`/`visible` variants whose exit mirrors the enter. Use as
53	 * initial="hidden" animate="visible" exit="hidden" under AnimatePresence.
54	 */
55	export function symmetric(offset: Offset = {}, duration: number = DURATION.base): Variants {
56	  return {
57	    hidden: { opacity: 0, ...offset, transition: exitTransition(duration) },
58	    visible: { opacity: 1, x: 0, y: 0, scale: 1, transition: enterTransition(duration) },
59	  };
60	}
61	
62	/** Parent variants: children enter in order and leave in reverse order. */
63	export function staggerGroup(stagger = STAGGER): Variants {
64	  return {
65	    hidden: { transition: { staggerChildren: stagger, staggerDirection: -1 } },
66	    visible: { transition: { staggerChildren: stagger } },
67	  };
68	}
