70	export const fade = symmetric({}, DURATION.fast);
71	export const rise = symmetric({ y: DISTANCE.md });
72	export const pop = symmetric({ scale: 0.6 }, DURATION.fast);
73	/** User bubbles arrive from the send side (right, slightly below). */
74	export const fromEnd = symmetric({ x: DISTANCE.lg, y: DISTANCE.sm });
75	/** Chat pane content when switching agents. */
76	export const paneSwap = symmetric({ y: DISTANCE.sm }, DURATION.fast);
77	
78	/** Height auto open/close; the content fades with it. */
79	export const collapse: Variants = {
